/**
 * useNavmeshFloodFill — 沿 NavMesh polygon 邻接图做 BFS，输出可达 polyRef 集合。
 *
 * 关键设计：
 * - **不破坏 navmesh**：参考 `floodFillPruneNavMesh` 的遍历模板，但仅收集 visited 集合，
 *   不调用 `navMesh.setPolyFlags(ref, 0)` 去禁用未访问的 poly。这样同一份烘焙产物
 *   可以反复换起点做 flood fill，避免每次都要重烘焙（实验工具的核心诉求）。
 * - **入口**：调用方先用 `NavMeshQuery.findNearestPoly()` 把世界坐标起点吸附到最近的
 *   polyRef，再把 polyRef 传进来。无 polyRef（0）直接返回空集，保持纯函数语义。
 * - **性能**：纯 JS BFS，typical polygon count 1k~10k，<10ms。openList 用数组当栈
 *   （后进先出，等价于 DFS 顺序，但对纯连通性判定无影响）。
 *
 * 注意：
 * - poly.firstLink() / tile.links(i) 是 Detour API；返回的 link index 用
 *   `Detour.DT_NULL_LINK` 作为链尾哨兵。
 * - `tile.links(i).ref()` 返回的 neiRef 可能为 0（无效），需过滤。
 * - 同一份起点 polyRef 多次调用应得到相同结果，无副作用。
 *
 * @changelog
 * | 版本   | 变更说明                                       | 关联                                                       |
 * | v1.0.0 | 初始实现：navmesh polygon 邻接 BFS（非破坏式） | REQ: navmesh-experiment-page TECH: plan §核心数据流 §架构 |
 * /@changelog
 *
 * @author linfan
 */
import { Detour, type NavMesh } from 'recast-navigation'

/**
 * 从起点 polyRef 出发，沿 polygon 邻接图做 BFS，返回所有可达的 polyRef 集合。
 *
 * @param navMesh   烘焙产物（不会被修改）
 * @param startPolyRef 起点 polyRef（NavMeshQuery.findNearestPoly 的输出）。
 *                     若为 0（起点未吸附到任何 poly），返回空 Set。
 * @returns 包含 startPolyRef 的可达 polyRef 集合
 */
export function floodFillFromPoly(
  navMesh: NavMesh,
  startPolyRef: number
): Set<number> {
  const visited = new Set<number>()
  if (!startPolyRef) return visited

  // 起点入栈
  const openList: number[] = [startPolyRef]
  visited.add(startPolyRef)

  while (openList.length > 0) {
    const ref = openList.pop() as number
    // 拿当前 poly + 所在 tile（tile 里存了 link 数组）
    const { poly, tile } = navMesh.getTileAndPolyByRefUnsafe(ref)

    // 遍历邻接链：从 poly.firstLink() 开始，沿 link.next() 一直走到 DT_NULL_LINK
    for (
      let i = poly.firstLink();
      i !== Detour.DT_NULL_LINK;
      i = tile.links(i).next()
    ) {
      const neiRef = tile.links(i).ref()
      if (!neiRef || visited.has(neiRef)) continue
      visited.add(neiRef)
      openList.push(neiRef)
    }
  }

  return visited
}

/**
 * 便捷版本：直接传世界坐标起点 + NavMeshQuery，内部做 findNearestPoly 再 flood fill。
 *
 * @param navMesh
 * @param navQuery
 * @param world  世界坐标起点 { x, y, z }
 * @param halfExtents  findNearestPoly 的搜索范围（默认 [2, 4, 2]，y 给大点更稳）
 * @returns { polyRef: 吸附到的 polyRef（0 表示未命中）, reachable: 可达集合 }
 */
export function floodFillFromWorld(
  navMesh: NavMesh,
  navQuery: { findNearestPoly: (pos: { x: number; y: number; z: number }, opts?: { halfExtents?: { x: number; y: number; z: number } }) => { success: boolean; nearestRef: number } },
  world: { x: number; y: number; z: number },
  halfExtents: { x: number; y: number; z: number } = { x: 2, y: 4, z: 2 }
): { polyRef: number; reachable: Set<number> } {
  const res = navQuery.findNearestPoly(world, { halfExtents })
  const polyRef = res.success ? res.nearestRef : 0
  if (!polyRef) {
    return { polyRef: 0, reachable: new Set() }
  }
  const reachable = floodFillFromPoly(navMesh, polyRef)
  return { polyRef, reachable }
}
