import { Box3, Matrix4, Quaternion, Vector3 } from 'three'
import type { ModuleRuntime, ModulesManifest } from '../types/modules'
import { useModulesStore } from '../stores/modules'

/**
 * 根据 manifest 构建 ModuleRuntime 列表（仅几何 AABB，不下载任何 GLB）。
 *
 * 障碍源已切换为「主预览区已加载的 GLB 地形」，因此这里只需把每个 module 的
 *   transform.position + bounds (+ rotation/scale)
 * 转成世界系的 worldBox 作为「该模块覆盖区域」标识：
 *   - 局部 AABB：center=(0,0,0), halfSize=bounds/2 （bounds 视为该 module 的总尺寸）
 *   - 应用 transform 矩阵后再 Box3.applyMatrix4 → 取轴对齐外包
 *
 * collision_name / ply_name 字段被忽略，仅保留在 spec 上以兼容上游 JSON。
 */
export async function loadCollisionsFromManifest(manifest: ModulesManifest): Promise<void> {
  const store = useModulesStore()

  // 取消令牌（保留：将来可能切换到异步源）
  const token = store.bumpCancelToken()
  store.setCollisionLoading(true)
  store.setCollisionProgress(0)

  const total = manifest.modules.length
  const runtimes: ModuleRuntime[] = manifest.modules.map((spec, index) => {
    const worldBox = computeModuleWorldBox(spec)
    return {
      ...spec,
      index,
      worldBox,
      group: null,
      loaded: true
    }
  })

  if (!store.isTokenAlive(token)) {
    store.setCollisionLoading(false)
    return
  }

  store.setModules(runtimes)
  store.setCollisionProgress(1)
  store.setCollisionLoading(false)

  // 让 await 调用方拿到一致的异步语义（即便我们是同步完成的）
  await Promise.resolve()
  void total
}

/**
 * 把 spec.transform + bounds 折算成世界 AABB。
 * 局部 AABB 假设以 (0,0,0) 为中心、尺寸为 bounds（与示例 JSON 中
 * 「position 即 module 中心、bounds 即模块尺寸」的语义一致）。
 *
 * ⚠️ 坐标系约定：
 *   - manifest 中 `transform.position` 已是 Three.js（Y-up）世界坐标
 *   - 但 `bounds` 沿用了源资产的 Z-up 约定：
 *       bounds.x = 东西方向尺寸（对应 Three.js X）
 *       bounds.y = 南北方向尺寸（对应 Three.js Z）  ← 不是高度！
 *       bounds.z = 高度（对应 Three.js Y）
 *     因此构造局部 AABB 时需要把 bounds.y / bounds.z 互换映射到 Three.js 轴上，
 *     否则俯视投影时浅蓝色 module 矩形会"长宽错位"。
 *
 * 注意：JSON 中 rotation 为 Hamilton 顺序 [w, x, y, z]；
 * 单位四元数 [1,0,0,0] 表示无旋转。
 */
function computeModuleWorldBox(spec: ModuleRuntime | { transform: ModulesManifest['modules'][number]['transform']; bounds: ModulesManifest['modules'][number]['bounds'] }): Box3 {
  const [px, py, pz] = spec.transform.position
  const [rw, rx, ry, rz] = spec.transform.rotation
  const [sx, sy, sz] = spec.transform.scale
  // bounds: Z-up (x=横, y=纵/深, z=高) → Three.js Y-up (x=横, y=高, z=纵/深)
  const half = new Vector3(spec.bounds.x / 2, spec.bounds.z / 2, spec.bounds.y / 2)

  const localBox = new Box3(half.clone().multiplyScalar(-1), half.clone())

  const q = new Quaternion(rx, ry, rz, rw)
  if (q.lengthSq() < 1e-6) q.identity()
  else q.normalize()

  const m = new Matrix4().compose(
    new Vector3(px, py, pz),
    q,
    new Vector3(sx || 1, sy || 1, sz || 1)
  )

  // Box3.applyMatrix4 会用变换后的 8 个角点重建 AABB
  const worldBox = localBox.clone().applyMatrix4(m)
  return worldBox
}
