import { defineStore } from 'pinia'
import { computed, ref, shallowRef, triggerRef } from 'vue'
import { Box3 } from 'three'
import type {
  GridResolution,
  ModuleRuntime,
  ModulesManifest,
  OverlayMode,
  ReachabilityResult,
  WalkableMap
} from '../types/modules'

/**
 * Modules / 可达性 store。
 * 设计要点：
 * - manifest / modules / walkableMap / reachability 都用 shallowRef 包装，避免 Vue 深度响应大体积 typed array
 * - 提供 markDirty 系列触发 overlay 重绘
 * - 取消令牌（cancelToken）由 store 持有，长任务（GLB 加载、栅格化）启动前自增，任务体内对比即可中止
 */
export const useModulesStore = defineStore('modules', () => {
  const manifest = shallowRef<ModulesManifest | null>(null)
  const modules = shallowRef<ModuleRuntime[]>([])

  const walkableMap = shallowRef<WalkableMap | null>(null)
  const reachability = shallowRef<ReachabilityResult | null>(null)

  /** 起点选择模式：开启后下一次 click 选起点，否则点击仅清除起点 */
  const startPickMode = ref<boolean>(true)

  /**
   * 用户在小地图上预选的起点（世界 XZ）。
   * 此状态仅表示"已选位置"，**不会触发栅格化或 reachability 计算**。
   * 用户在右侧面板点击「生成可达地块树」按钮后，才会真正栅格化 + 计算可达性。
   * 当 reachability 被设置或清空、或 manifest 被替换时同步清空。
   */
  const pendingStart = ref<{ x: number; z: number } | null>(null)

  /** 显示模式 */
  const overlayMode = ref<OverlayMode>('reach')

  /** 栅格分辨率与坡度阈值（度数） */
  const gridResolution = ref<GridResolution>(1024)
  const slopeThresholdDeg = ref<number>(45)

  /** 加载/栅格化的进度（0~1） */
  const collisionLoadProgress = ref<number>(0)
  const isLoadingCollisions = ref<boolean>(false)
  const rasterizeProgress = ref<number>(0)
  const isRasterizing = ref<boolean>(false)
  const rasterizeStartedAt = ref<number>(0)

  /** Hover 高亮的模块（用于 overlay & ReachableList 互动） */
  const hoveredModuleName = ref<string | null>(null)

  /** 全局取消令牌：自增即视为旧任务作废 */
  const cancelToken = ref<number>(0)

  /** overlay 重绘脏标记 */
  const overlayDirty = ref<number>(0)

  /** 合并所有已加载 module 的 worldBox（用作栅格化范围） */
  const mergedCollisionBox = computed<Box3 | null>(() => {
    const list = modules.value
    if (list.length === 0) return null
    const merged = new Box3()
    let inited = false
    for (const m of list) {
      if (!m.loaded || m.worldBox.isEmpty()) continue
      if (!inited) {
        merged.copy(m.worldBox)
        inited = true
      } else {
        merged.union(m.worldBox)
      }
    }
    return inited ? merged : null
  })

  const moduleCount = computed(() => modules.value.length)
  const loadedModuleCount = computed(() => modules.value.filter((m) => m.loaded).length)
  const hasManifest = computed(() => manifest.value !== null)
  const hasWalkable = computed(() => walkableMap.value !== null)
  const hasReachability = computed(() => reachability.value !== null)

  function setManifest(m: ModulesManifest | null) {
    manifest.value = m
    walkableMap.value = null
    reachability.value = null
    pendingStart.value = null
    invalidateOverlay()
  }

  function setModules(list: ModuleRuntime[]) {
    modules.value = list
    triggerRef(modules)
    invalidateOverlay()
  }

  function patchModule(index: number, patch: Partial<ModuleRuntime>) {
    const list = modules.value
    if (!list[index]) return
    list[index] = { ...list[index], ...patch }
    modules.value = [...list]
    triggerRef(modules)
    invalidateOverlay()
  }

  function setWalkableMap(map: WalkableMap | null) {
    walkableMap.value = map
    // walkable 变了 → 旧的 reachability 失效
    reachability.value = null
    invalidateOverlay()
  }

  function setReachability(r: ReachabilityResult | null) {
    reachability.value = r
    // reachability 一旦设置成功，pendingStart 已被消费，可以清空
    if (r) pendingStart.value = null
    invalidateOverlay()
  }

  function setPendingStart(p: { x: number; z: number } | null) {
    pendingStart.value = p
    invalidateOverlay()
  }

  function setOverlayMode(m: OverlayMode) {
    overlayMode.value = m
    invalidateOverlay()
  }

  function setGridResolution(r: GridResolution) {
    gridResolution.value = r
  }

  function setSlopeDeg(deg: number) {
    slopeThresholdDeg.value = deg
  }

  function setHoveredModule(name: string | null) {
    hoveredModuleName.value = name
    invalidateOverlay()
  }

  function setStartPickMode(v: boolean) {
    startPickMode.value = v
  }

  function setCollisionLoading(v: boolean) {
    isLoadingCollisions.value = v
    if (!v) collisionLoadProgress.value = 0
  }

  function setCollisionProgress(v: number) {
    collisionLoadProgress.value = v
  }

  function setRasterizing(v: boolean) {
    isRasterizing.value = v
    if (v) rasterizeStartedAt.value = Date.now()
    if (!v) rasterizeProgress.value = 0
  }

  function setRasterizeProgress(v: number) {
    rasterizeProgress.value = v
  }

  function clearStart() {
    reachability.value = null
    pendingStart.value = null
    invalidateOverlay()
  }

  function clearAll() {
    manifest.value = null
    modules.value = []
    walkableMap.value = null
    reachability.value = null
    pendingStart.value = null
    invalidateOverlay()
  }

  function invalidateOverlay() {
    overlayDirty.value++
  }

  function bumpCancelToken(): number {
    cancelToken.value += 1
    return cancelToken.value
  }

  function isTokenAlive(token: number): boolean {
    return token === cancelToken.value
  }

  return {
    // state
    manifest,
    modules,
    walkableMap,
    reachability,
    startPickMode,
    pendingStart,
    overlayMode,
    gridResolution,
    slopeThresholdDeg,
    collisionLoadProgress,
    isLoadingCollisions,
    rasterizeProgress,
    isRasterizing,
    rasterizeStartedAt,
    hoveredModuleName,
    cancelToken,
    overlayDirty,
    // computed
    mergedCollisionBox,
    moduleCount,
    loadedModuleCount,
    hasManifest,
    hasWalkable,
    hasReachability,
    // actions
    setManifest,
    setModules,
    patchModule,
    setWalkableMap,
    setReachability,
    setPendingStart,
    setOverlayMode,
    setGridResolution,
    setSlopeDeg,
    setHoveredModule,
    setStartPickMode,
    setCollisionLoading,
    setCollisionProgress,
    setRasterizing,
    setRasterizeProgress,
    clearStart,
    clearAll,
    invalidateOverlay,
    bumpCancelToken,
    isTokenAlive
  }
})
