import type { ModuleSpec, ModulesManifest } from '../types/modules'

export interface ManifestParseResult {
  ok: boolean
  manifest?: ModulesManifest
  error?: string
}

/**
 * 解析 + 校验 modules JSON 文本。
 * 仅做轻量手写校验，避免引入 zod/yup 等依赖。
 */
export function parseManifestText(text: string): ManifestParseResult {
  if (!text || !text.trim()) {
    return { ok: false, error: 'JSON 为空' }
  }
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch (err) {
    console.error('[ManifestLoader] JSON 解析失败', err)
    return { ok: false, error: `JSON 格式非法：${(err as Error).message}` }
  }
  if (typeof raw !== 'object' || raw === null) {
    return { ok: false, error: '根节点必须是对象' }
  }
  const r = raw as Record<string, unknown>
  // baseUrl 在「忽略 collision_name」模式下不强制；缺省给空串，仅作展示
  const baseUrlRaw = typeof r.baseUrl === 'string' ? r.baseUrl : ''
  if (!Array.isArray(r.modules) || r.modules.length === 0) {
    return { ok: false, error: 'modules 必须是非空数组' }
  }

  const modules: ModuleSpec[] = []
  for (let i = 0; i < r.modules.length; i++) {
    const item = r.modules[i] as Record<string, unknown>
    const idx = `modules[${i}]`
    if (!item || typeof item !== 'object') {
      return { ok: false, error: `${idx} 必须是对象` }
    }
    if (typeof item.name !== 'string') {
      return { ok: false, error: `${idx}.name 缺失或非字符串` }
    }
    const t = item.transform as Record<string, unknown> | undefined
    if (!t || typeof t !== 'object') {
      return { ok: false, error: `${idx}.transform 缺失` }
    }
    const pos = readNumberArr(t.position, 3)
    const rot = readNumberArr(t.rotation, 4)
    const scl = readNumberArr(t.scale, 3)
    if (!pos) return { ok: false, error: `${idx}.transform.position 必须是 3 个数` }
    if (!rot) return { ok: false, error: `${idx}.transform.rotation 必须是 4 个数（[w,x,y,z]）` }
    if (!scl) return { ok: false, error: `${idx}.transform.scale 必须是 3 个数` }
    const b = item.bounds as Record<string, unknown> | undefined
    if (!b || typeof b.x !== 'number' || typeof b.y !== 'number' || typeof b.z !== 'number') {
      return { ok: false, error: `${idx}.bounds 必须是 {x,y,z} 三个数` }
    }
    const collisions = item.collision_name
    if (collisions !== undefined && (!Array.isArray(collisions) || collisions.some((s) => typeof s !== 'string'))) {
      return { ok: false, error: `${idx}.collision_name 必须是字符串数组（或省略）` }
    }
    const plys = item.ply_name
    if (plys !== undefined && (!Array.isArray(plys) || plys.some((s) => typeof s !== 'string'))) {
      return { ok: false, error: `${idx}.ply_name 必须是字符串数组（或省略）` }
    }
    modules.push({
      name: item.name,
      transform: {
        position: pos as [number, number, number],
        rotation: rot as [number, number, number, number],
        scale: scl as [number, number, number]
      },
      bounds: { x: b.x, y: b.y, z: b.z },
      collision_name: (collisions ?? []) as string[],
      ply_name: (plys ?? []) as string[]
    })
  }

  let baseUrl = baseUrlRaw
  if (baseUrl && !baseUrl.endsWith('/')) baseUrl += '/'

  const manifest: ModulesManifest = {
    baseUrl,
    morton: Boolean(r.morton),
    fileType: typeof r.fileType === 'string' ? r.fileType : 'splat',
    modules
  }
  return { ok: true, manifest }
}

function readNumberArr(v: unknown, len: number): number[] | null {
  if (!Array.isArray(v) || v.length !== len) return null
  const out: number[] = []
  for (const n of v) {
    if (typeof n !== 'number' || !Number.isFinite(n)) return null
    out.push(n)
  }
  return out
}
