/**
 * useNavmeshPathfinding — 在烘焙好的 NavMesh 上做 A* + funnel 平滑寻路。
 *
 * 关键设计：
 * - 直接复用 `NavMeshQuery.computePath()`：它是 recast-navigation-js 的高层封装，内部
 *   等价于 findNearestPoly(start) + findNearestPoly(end) + findPath + findStraightPath
 *   （findStraightPath 即 funnel 算法），一次调用拿到平滑路径，无需自己拼。
 * - **输出 flat Float32Array**：直接给 Three.js BufferGeometry 用，避免 Vector3[] 转 flat
 *   的二次开销；调用方按 `points.length / 3` 取点数。
 * - **失败处理**：返回 `{ ok: false, error, points: 空 Float32Array }`，由 UI 显示
 *   "起点/终点不可达"；不抛异常。
 * - **不缓存**：调用方负责在起点/终点变化时主动重算（store 已有 setStart/setEnd 清空 path 的语义）。
 *
 * 边界情况：
 * - 起点 = 终点 / 距离过近：computePath 仍然会返回长度 ≥ 1 的路径（至少含起点），照常输出。
 * - 起点/终点未吸附到任何 poly：computePath 内部 findNearestPoly 失败 → success=false。
 * - 起点终点不在同一连通分量：success=false，返回 error.name="path-not-found" 之类。
 *
 * @changelog
 * | 版本   | 变更说明                                          | 关联                                                       |
 * | v1.0.0 | 初始实现：computePath 封装 + flat Float32Array 输出 | REQ: navmesh-experiment-page TECH: plan §核心数据流       |
 * /@changelog
 *
 * @author linfan
 */
import type { NavMeshQuery } from 'recast-navigation'

export interface PathfindResult {
  ok: boolean
  /** 平铺顶点（x0, y0, z0, x1, y1, z1, ...）。失败时长度为 0。 */
  points: Float32Array
  /** 顶点个数（= points.length / 3） */
  pointCount: number
  error?: string
}

/**
 * 在 navmesh 上寻路并返回 funnel 平滑路径。
 *
 * @param navQuery 烘焙产物中的 NavMeshQuery
 * @param start 起点（世界坐标）
 * @param end   终点（世界坐标）
 * @param halfExtents findNearestPoly 的搜索范围（默认 [2, 4, 2]）
 */
export function findPath(
  navQuery: NavMeshQuery,
  start: { x: number; y: number; z: number },
  end: { x: number; y: number; z: number },
  halfExtents: { x: number; y: number; z: number } = { x: 2, y: 4, z: 2 }
): PathfindResult {
  const t0 = performance.now()

  const res = navQuery.computePath(start, end, {
    halfExtents,
    maxPathPolys: 512,
    maxStraightPathPoints: 512
  })

  if (!res.success || !res.path || res.path.length === 0) {
    const reason = res.error?.name || 'no-path'
    console.warn(`[navmesh] pathfind failed: ${reason}`)
    return {
      ok: false,
      points: new Float32Array(0),
      pointCount: 0,
      error: reason
    }
  }

  // path: Vector3[] → flat Float32Array
  const count = res.path.length
  const points = new Float32Array(count * 3)
  for (let i = 0; i < count; i++) {
    const p = res.path[i]
    points[i * 3] = p.x
    points[i * 3 + 1] = p.y
    points[i * 3 + 2] = p.z
  }

  const ms = performance.now() - t0
  console.info(`[navmesh] pathfind ok: ${count} pts in ${ms.toFixed(1)}ms`)

  return {
    ok: true,
    points,
    pointCount: count
  }
}
