import {
  AmbientLight,
  DirectionalLight,
  HemisphereLight,
  Material,
  Mesh,
  Object3D,
  Scene,
  Texture
} from 'three'

let _scene: Scene | null = null
let _collisionScene: Scene | null = null

function createScene(): Scene {
  const scene = new Scene()

  // 半球光：天空青色 + 地面深蓝，给地形带来氛围色
  const hemi = new HemisphereLight(0x88ccff, 0x223355, 0.55)
  scene.add(hemi)

  // 顶部方向光：对俯视小地图最关键，模拟正午光
  const topDir = new DirectionalLight(0xffffff, 1.0)
  topDir.position.set(0, 200, 0)
  topDir.target.position.set(0, 0, 0)
  scene.add(topDir)
  scene.add(topDir.target)

  // 侧向方向光：3D 预览时增加体积感
  const sideDir = new DirectionalLight(0xc7e4ff, 0.45)
  sideDir.position.set(120, 80, 60)
  scene.add(sideDir)

  // 环境光保底
  const ambient = new AmbientLight(0xffffff, 0.18)
  scene.add(ambient)

  return scene
}

/**
 * 独立的碰撞场景：
 * - 仅供 Raycaster 在栅格化阶段使用，不参与渲染
 * - 与主 scene 解耦，避免污染预览/小地图视觉
 */
function createCollisionScene(): Scene {
  return new Scene()
}

export function useThreeScene() {
  if (!_scene) _scene = createScene()
  if (!_collisionScene) _collisionScene = createCollisionScene()
  const scene = _scene
  const collisionScene = _collisionScene

  function addObject(obj: Object3D) {
    scene.add(obj)
  }

  function removeObject(obj: Object3D) {
    scene.remove(obj)
    disposeObject(obj)
  }

  function addCollisionObject(obj: Object3D) {
    collisionScene.add(obj)
  }

  function removeCollisionObject(obj: Object3D) {
    collisionScene.remove(obj)
    disposeObject(obj)
  }

  function clearCollisionScene() {
    const toRemove = [...collisionScene.children]
    for (const child of toRemove) {
      collisionScene.remove(child)
      disposeObject(child)
    }
  }

  return {
    scene,
    collisionScene,
    addObject,
    removeObject,
    addCollisionObject,
    removeCollisionObject,
    clearCollisionScene
  }
}

/** 递归释放 Object3D 的 geometry/material/texture */
export function disposeObject(obj: Object3D) {
  obj.traverse((child) => {
    const mesh = child as Mesh
    if (mesh.isMesh) {
      mesh.geometry?.dispose()
      const mat = mesh.material
      if (Array.isArray(mat)) {
        mat.forEach(disposeMaterial)
      } else if (mat) {
        disposeMaterial(mat)
      }
    }
  })
}

function disposeMaterial(material: Material) {
  // 释放材质上常见的纹理槽
  const m = material as unknown as Record<string, unknown>
  for (const key of Object.keys(m)) {
    const value = m[key]
    if (value && (value as Texture).isTexture) {
      ;(value as Texture).dispose()
    }
  }
  material.dispose()
}
