<script setup lang="ts">
import { computed, ref } from 'vue'
import { FileJson, Upload, Loader2, Trash2, AlertCircle, Info } from 'lucide-vue-next'
import { parseManifestText } from '../composables/useManifestLoader'
import { loadCollisionsFromManifest } from '../composables/useCollisionLoader'
import { useModulesStore } from '../stores/modules'
import { useTerrainStore } from '../stores/terrain'

const store = useModulesStore()
const terrainStore = useTerrainStore()
const fileInputRef = ref<HTMLInputElement | null>(null)
const isDragging = ref(false)
const errorText = ref<string | null>(null)
const pasteText = ref<string>('')
const showPaste = ref<boolean>(false)

const hasTerrain = computed(() => terrainStore.count > 0)

function pickFile() {
  fileInputRef.value?.click()
}

async function onInputChange(e: Event) {
  const input = e.target as HTMLInputElement
  const file = input.files?.[0]
  input.value = ''
  if (file) await readAndApply(file)
}

async function onDrop(e: DragEvent) {
  e.preventDefault()
  isDragging.value = false
  const file = e.dataTransfer?.files?.[0]
  if (file) await readAndApply(file)
}

function onDragOver(e: DragEvent) {
  e.preventDefault()
  isDragging.value = true
}

function onDragLeave() {
  isDragging.value = false
}

async function readAndApply(file: File) {
  errorText.value = null
  const text = await file.text()
  await applyText(text)
}

async function applyPaste() {
  await applyText(pasteText.value)
}

async function applyText(text: string) {
  errorText.value = null
  const result = parseManifestText(text)
  if (!result.ok || !result.manifest) {
    errorText.value = result.error ?? '解析失败'
    console.error('[ManifestPanel] 解析失败', result.error)
    return
  }
  store.setManifest(result.manifest)
  await loadCollisionsFromManifest(result.manifest)
  // 注意：anchor 推导采用候选剪枝 + 局部 A*，不再需要全图栅格化的 walkable map。
  // 用户可以直接在右侧 Anchor 面板「生成默认」并「计算邻接」。
}

function clearAll() {
  store.clearAll()
  errorText.value = null
  pasteText.value = ''
}
</script>

<template>
  <div class="glass-card p-3 flex flex-col gap-3">
    <div class="flex items-center justify-between px-1">
      <div class="flex items-center gap-2">
        <FileJson class="w-4 h-4 text-indigo-300" />
        <span class="text-sm font-semibold tracking-wide">Modules JSON</span>
        <span v-if="store.hasManifest" class="chip">
          {{ store.loadedModuleCount }} / {{ store.moduleCount }}
        </span>
      </div>
      <div v-if="store.hasManifest" class="flex items-center gap-1">
        <button class="btn-ghost" title="清空" @click="clearAll">
          <Trash2 class="w-3.5 h-3.5" />
        </button>
      </div>
    </div>

    <!-- 上传区 -->
    <div
      v-if="!store.hasManifest"
      class="relative rounded-lg border-2 border-dashed transition-all cursor-pointer"
      :class="
        isDragging
          ? 'border-indigo-400 bg-indigo-400/10'
          : 'border-white/15 hover:border-indigo-400/60 hover:bg-white/5'
      "
      @click="pickFile"
      @dragover="onDragOver"
      @dragleave="onDragLeave"
      @drop="onDrop"
    >
      <input
        ref="fileInputRef"
        type="file"
        accept=".json,application/json"
        class="hidden"
        @change="onInputChange"
      />
      <div class="px-4 py-4 flex flex-col items-center text-center">
        <div
          class="w-9 h-9 rounded-lg bg-white/5 border border-white/10 flex items-center justify-center mb-2"
        >
          <Upload class="w-4 h-4 text-indigo-300" />
        </div>
        <div class="text-xs font-medium text-slate-100">上传 modules JSON</div>
        <div class="text-[10px] text-slate-400 mt-0.5">
          点击或拖入 .json · 仅解析 baseUrl + modules[] 几何
        </div>
      </div>
    </div>

    <!-- 解析中提示（极快，主要为视觉过渡） -->
    <div
      v-if="store.isLoadingCollisions"
      class="rounded-lg bg-white/[0.03] border border-white/10 px-3 py-2 flex items-center gap-2 text-[11px]"
    >
      <Loader2 class="w-3.5 h-3.5 text-indigo-300 animate-spin" />
      <span class="text-slate-300 flex-1">解析 modules…</span>
    </div>

    <!-- 已加载 manifest 概览 -->
    <div
      v-if="store.hasManifest && !store.isLoadingCollisions"
      class="rounded-lg bg-white/[0.03] border border-white/5 px-3 py-2 text-[11px] flex flex-col gap-1"
    >
      <div class="flex justify-between text-slate-400">
        <span>baseUrl</span>
        <span
          class="font-mono text-slate-300 truncate max-w-[200px]"
          :title="store.manifest!.baseUrl"
        >
          {{ store.manifest!.baseUrl || '—' }}
        </span>
      </div>
      <div class="flex justify-between text-slate-400">
        <span>fileType</span>
        <span class="font-mono">{{ store.manifest!.fileType }}</span>
      </div>
    </div>

    <!-- 提示：缺少地形则不能进行 anchor 推导（需要 terrain raycast） -->
    <div
      v-if="store.hasManifest && !hasTerrain"
      class="flex items-start gap-2 px-3 py-2 rounded-md bg-amber-500/10 border border-amber-500/30 text-[11px] text-amber-200"
    >
      <Info class="w-3.5 h-3.5 mt-0.5 shrink-0" />
      <span>
        请先在「3D 地形」面板上传 GLB —— 障碍源使用主预览区已加载的地形 mesh，
        modules JSON 仅提供地块 AABB。
      </span>
    </div>

    <!-- 粘贴入口 -->
    <button
      v-if="!store.hasManifest"
      class="text-[10px] text-slate-500 hover:text-cyan-glow transition-colors text-left px-1 cursor-pointer"
      @click="showPaste = !showPaste"
    >
      {{ showPaste ? '— 收起粘贴框' : '+ 或粘贴 JSON 文本' }}
    </button>
    <div v-if="!store.hasManifest && showPaste" class="flex flex-col gap-1.5">
      <textarea
        v-model="pasteText"
        rows="4"
        placeholder='{"baseUrl":"...","modules":[...]}'
        class="w-full rounded-md bg-black/30 border border-white/10 text-[11px] text-slate-200 font-mono px-2 py-1.5 focus:outline-none focus:border-cyan-glow/60 resize-none"
      />
      <button
        class="btn-cyan justify-center"
        :disabled="!pasteText.trim()"
        :class="{ 'opacity-50 cursor-not-allowed': !pasteText.trim() }"
        @click="applyPaste"
      >
        解析并加载
      </button>
    </div>

    <!-- 错误提示 -->
    <div
      v-if="errorText"
      class="flex items-start gap-2 px-3 py-2 rounded-md bg-rose-500/10 border border-rose-500/30 text-[11px] text-rose-300"
    >
      <AlertCircle class="w-3.5 h-3.5 mt-0.5 shrink-0" />
      <span>{{ errorText }}</span>
    </div>
  </div>
</template>
