<script setup lang="ts">
/**
 * NavmeshView — Navmesh 实验台主视图。
 *
 * 职责（编排层）：
 * - 左侧：UploadPanel / ManifestPanel（复用，确保用户能上传 GLB）+ NavmeshParamsPanel
 * - 中央：3D 视口（独立 renderer 复用 globalScene）+ 模式切换胶囊按钮 + 顶部 error banner + loading mask
 * - 右下角：NavmeshLegend
 *
 * 数据流：
 * - 用户点 "应用" → 调用 bakeNavmesh → store.setBakeResult → render.setPolygons + setModuleHalos
 * - 用户切到 "选起点" 模式后点击 3D → onPick → findNearestPoly + flood fill + polyToModule → render 全量更新
 * - 用户切到 "选终点" 模式后点击 → onPick → findPath → render.setPath
 *
 * @author linfan
 */
import { computed, onBeforeUnmount, ref, watch, markRaw } from 'vue'
import {
  Hexagon,
  AlertCircle,
  Loader2,
  Crosshair,
  Flag,
  Trash2,
  Download,
  X
} from 'lucide-vue-next'
import UploadPanel from './UploadPanel.vue'
import ManifestPanel from './ManifestPanel.vue'
import NavmeshParamsPanel from './NavmeshParamsPanel.vue'
import NavmeshLegend from './NavmeshLegend.vue'
import NavmeshMinimap from './NavmeshMinimap.vue'
import { useTerrainStore } from '../stores/terrain'
import { useModulesStore } from '../stores/modules'
import { useNavmeshStore, type NavmeshBakeParams } from '../stores/navmesh'
import { useNavmeshPreview } from '../composables/useNavmeshPreview'
import {
  bakeNavmesh,
  ensureRecastInited,
  disposeBake,
  type BakeOutput
} from '../composables/useNavmeshBaker'
import { createNavmeshRender, type NavmeshRenderHandle } from '../composables/useNavmeshRender'
import { floodFillFromPoly } from '../composables/useNavmeshFloodFill'
import { mapPolyToModule } from '../composables/usePolyToModule'
import { findPath } from '../composables/useNavmeshPathfinding'
import { downloadNavmeshAnnotatedManifestJson } from '../composables/useNavmeshReachabilityExport'

const containerRef = ref<HTMLDivElement | null>(null)
const canvasRef = ref<HTMLCanvasElement | null>(null)

const terrainStore = useTerrainStore()
const modulesStore = useModulesStore()
const store = useNavmeshStore()

/** 渲染句柄（markRaw 防止响应式 proxy 干扰 Three 对象） */
let renderHandle: NavmeshRenderHandle | null = null

/* ---------- 3D 预览：拾取回调 ---------- */
function handlePick(point: { x: number; y: number; z: number }) {
  if (!store.navMeshRef || !store.navQueryRef) return
  const mode = store.pickMode
  if (mode === 'off') return
  if (mode === 'start') {
    setStart(point)
  } else if (mode === 'end') {
    setEnd(point)
  }
}

const { focusBox } = useNavmeshPreview({
  canvasRef: () => canvasRef.value,
  containerRef: () => containerRef.value,
  onPick: handlePick
})

/* ---------- 烘焙 ---------- */
async function applyBake(params: NavmeshBakeParams) {
  if (terrainStore.terrains.length === 0) {
    store.setError('请先在左侧上传 navmesh GLB（或几何 GLB）')
    return
  }
  store.setError(null)
  store.setLoading(true, '初始化 Recast wasm…')
  // 取 token 用于"丢弃 stale 结果"
  const token = store.bumpBakeToken()
  let out: BakeOutput | null = null
  try {
    await ensureRecastInited()
    if (!store.isTokenAlive(token)) return
    store.setLoading(true, '烘焙 navmesh…')
    // 同步阻塞，但前面已 setLoading，UI 会先重绘 mask 再阻塞
    await new Promise((r) => setTimeout(r, 0)) // 让出一帧给 UI 渲染 loading mask
    if (!store.isTokenAlive(token)) return
    out = bakeNavmesh({ terrains: terrainStore.terrains, params })
    if (!store.isTokenAlive(token)) {
      disposeBake(out)
      return
    }
    // 旧实例释放（store.setBakeResult 不会 destroy 旧的，需手动）
    if (store.navMeshRef) {
      try {
        store.navQueryRef?.destroy()
        store.navMeshRef.destroy()
      } catch (err) {
        console.warn('[navmesh] dispose old navmesh failed', err)
      }
    }
    store.setBakeResult(out.navMesh, out.navQuery, out.polygons, out.bakeMs)
    // 渲染层：重建 navmesh polygon
    if (renderHandle) {
      renderHandle.setPolygons(out.polygons)
      renderHandle.setReachable(new Set())
      renderHandle.setStartMarker(null)
      renderHandle.setEndMarker(null)
      renderHandle.setPath(new Float32Array(0))
      // module halo 默认 neutral
      updateModuleHalos()
    }
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e)
    console.error('[navmesh] bake failed', e)
    store.setError(`烘焙失败：${msg}`)
    if (out) disposeBake(out)
  } finally {
    if (store.isTokenAlive(token)) store.setLoading(false)
  }
}

/* ---------- 起点 / 终点 / flood fill / 寻路 ---------- */
function setStart(point: { x: number; y: number; z: number }) {
  if (!store.navMeshRef || !store.navQueryRef) return
  store.setError(null)
  // findNearestPoly
  const halfExtents = { x: 2, y: 4, z: 2 }
  const res = store.navQueryRef.findNearestPoly(point, { halfExtents })
  if (!res.success || !res.nearestRef) {
    store.setError('起点未吸附到任何 polygon（请点击在 navmesh 覆盖区域内）')
    return
  }
  const polyRef = res.nearestRef
  store.setStart(point, polyRef)
  // flood fill
  const reachable = floodFillFromPoly(store.navMeshRef, polyRef)
  // poly → module 映射
  const mapped = mapPolyToModule(store.polygons, reachable, modulesStore.modules)
  store.setReachable(
    reachable,
    mapped.reachableModuleIds,
    mapped.unreachableModuleIds,
    mapped.crossModulePolyCount
  )
  // 渲染更新
  if (renderHandle) {
    renderHandle.setStartMarker(point)
    renderHandle.setReachable(reachable)
    updateModuleHalos()
  }
  console.info(
    `[navmesh] flood fill: ${reachable.size}/${store.polyCount} polys, ${mapped.reachableModuleIds.size} modules reachable`
  )
}

function setEnd(point: { x: number; y: number; z: number }) {
  if (!store.navMeshRef || !store.navQueryRef) return
  if (!store.startPoint) {
    store.setError('请先选起点再选终点')
    return
  }
  store.setError(null)
  const res = store.navQueryRef.findNearestPoly(point, {
    halfExtents: { x: 2, y: 4, z: 2 }
  })
  if (!res.success || !res.nearestRef) {
    store.setError('终点未吸附到任何 polygon')
    return
  }
  store.setEnd(point, res.nearestRef)
  const path = findPath(store.navQueryRef, store.startPoint, point)
  if (!path.ok) {
    store.setError(`寻路失败：${path.error || '路径不可达'}`)
    if (renderHandle) {
      renderHandle.setEndMarker(point)
      renderHandle.setPath(new Float32Array(0))
    }
    return
  }
  store.setPath(path.points)
  if (renderHandle) {
    renderHandle.setEndMarker(point)
    renderHandle.setPath(path.points)
  }
}

function updateModuleHalos() {
  if (!renderHandle) return
  const items = modulesStore.modules
    .filter((m) => !m.worldBox.isEmpty())
    .map((m) => {
      let state: 'reach' | 'unreach' | 'neutral' = 'neutral'
      if (store.reachableModuleIds.has(m.name)) state = 'reach'
      else if (store.unreachableModuleIds.has(m.name)) state = 'unreach'
      return { name: m.name, box: m.worldBox, state }
    })
  renderHandle.setModuleHalos(items)
}

/* ---------- 模式切换 / 清除 ---------- */
function setPickMode(m: 'start' | 'end' | 'off') {
  store.setPickMode(m)
}

function clearAll() {
  store.clearFloodAndPath()
  if (renderHandle) {
    renderHandle.setReachable(new Set())
    renderHandle.setStartMarker(null)
    renderHandle.setEndMarker(null)
    renderHandle.setPath(new Float32Array(0))
    updateModuleHalos()
  }
}

/* ---------- 导出：带 reachableNeighbors 的 manifest ---------- */
function exportManifest() {
  try {
    store.setError(null)
    downloadNavmeshAnnotatedManifestJson()
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e)
    console.error('[navmesh] export failed', e)
    store.setError(`导出失败：${msg}`)
  }
}

/* ---------- 生命周期 ---------- */
import { useThreeScene } from '../composables/useThreeScene'
const { scene } = useThreeScene()

// 在 Vue mount 之前先建好 render handle 并挂到 scene；卸载时 dispose
const handle = createNavmeshRender()
renderHandle = markRaw(handle)
scene.add(handle.root)

// modules 加载完成后刷新 halo
watch(
  () => modulesStore.loadedModuleCount,
  () => updateModuleHalos()
)

/* ---------- 二维小地图 → 3D 联动：选中 module 时聚焦 + 高亮框 ---------- */
watch(
  () => store.selectedModuleId,
  (id) => {
    if (!renderHandle) return
    if (!id) {
      renderHandle.setSelectedModule(null)
      return
    }
    const target = modulesStore.modules.find((m) => m.name === id)
    if (!target || target.worldBox.isEmpty()) {
      renderHandle.setSelectedModule(null)
      return
    }
    renderHandle.setSelectedModule(target.worldBox)
    focusBox(target.worldBox)
  }
)

onBeforeUnmount(() => {
  if (renderHandle) {
    renderHandle.dispose()
    renderHandle = null
  }
  // navmesh 实例：从 store 释放（这里 store 持有，clearBakeResult 会 destroy）
  store.clearBakeResult()
})

/* ---------- 派生展示态 ---------- */
const hasGeometry = computed(() => terrainStore.terrains.length > 0)
const showEmpty = computed(() => !hasGeometry.value && !store.hasNavmesh)

const SIDEBAR_KEY = 'gtm.navmesh.sidebar.width'
const MIN_W = 280
const MAX_W = 480
const DEFAULT_W = 320
const sidebarWidth = ref<number>(loadInitialWidth())
const dragging = ref(false)

function loadInitialWidth(): number {
  const raw = localStorage.getItem(SIDEBAR_KEY)
  const n = raw ? Number(raw) : NaN
  if (!Number.isFinite(n)) return DEFAULT_W
  return Math.min(MAX_W, Math.max(MIN_W, n))
}
function clampW(w: number) {
  return Math.min(MAX_W, Math.max(MIN_W, w))
}
function onDragMove(e: MouseEvent) {
  if (!dragging.value) return
  sidebarWidth.value = clampW(e.clientX - 12)
}
function endDrag() {
  if (!dragging.value) return
  dragging.value = false
  document.body.style.cursor = ''
  document.body.style.userSelect = ''
  window.removeEventListener('mousemove', onDragMove)
  window.removeEventListener('mouseup', endDrag)
  try {
    localStorage.setItem(SIDEBAR_KEY, String(Math.round(sidebarWidth.value)))
  } catch {
    /* ignore */
  }
}
function startDrag(e: MouseEvent) {
  e.preventDefault()
  dragging.value = true
  document.body.style.cursor = 'col-resize'
  document.body.style.userSelect = 'none'
  window.addEventListener('mousemove', onDragMove)
  window.addEventListener('mouseup', endDrag)
}
</script>

<template>
  <main class="flex-1 min-h-0 flex p-3 gap-1">
    <!-- 左侧：二维小地图 + 上传 + manifest + 烘焙参数 -->
    <!--
      关键：必须加 min-h-0 才能让 overflow-y-auto 生效。
      flex 子项默认 min-height: auto（= 内容高度），会撑出父容器，导致内容溢出到 main 之外，
      aside 自身永远不会触发滚动条。min-h-0 解锁压缩，让 aside 能被父 flex 限定到屏幕高度，
      内容超出时才会出现滚动条。
    -->
    <aside
      class="shrink-0 min-h-0 flex flex-col gap-3 overflow-y-auto overflow-x-hidden pr-1"
      :style="{ width: sidebarWidth + 'px' }"
    >
      <NavmeshMinimap />
      <UploadPanel />
      <ManifestPanel />
      <NavmeshParamsPanel @apply="applyBake" />
    </aside>

    <!-- 拖拽分隔条 -->
    <div
      class="group relative shrink-0 w-2 cursor-col-resize flex items-center justify-center"
      :class="dragging ? 'bg-cyan-glow/20' : 'hover:bg-white/5'"
      title="拖动调整侧边栏宽度"
      role="separator"
      aria-orientation="vertical"
      @mousedown="startDrag"
    >
      <div
        class="w-[2px] h-10 rounded-full transition-colors"
        :class="dragging ? 'bg-cyan-glow' : 'bg-white/15 group-hover:bg-cyan-glow/70'"
      />
    </div>

    <!-- 中央 3D 视口 -->
    <section class="flex-1 min-w-0 relative rounded-xl border border-white/5 overflow-hidden">
      <div ref="containerRef" class="absolute inset-0">
        <canvas ref="canvasRef" class="block w-full h-full" />
      </div>

      <!-- 顶部错误 banner -->
      <div
        v-if="store.error"
        class="absolute top-2 left-2 right-2 flex items-start gap-2 px-3 py-2 rounded-md bg-red-500/15 border border-red-400/40 text-[11px] text-red-200 backdrop-blur-glass animate-fade-in"
      >
        <AlertCircle class="w-3.5 h-3.5 mt-0.5 shrink-0" />
        <div class="flex-1 break-words">{{ store.error }}</div>
        <button
          type="button"
          class="shrink-0 hover:text-white cursor-pointer"
          @click="store.setError(null)"
        >
          <X class="w-3.5 h-3.5" />
        </button>
      </div>

      <!-- 右上角模式切换 -->
      <div
        v-if="store.hasNavmesh"
        class="absolute top-2 right-2 flex items-center gap-1 p-1 rounded-lg bg-black/30 border border-white/10 backdrop-blur-glass"
      >
        <button
          type="button"
          class="px-2.5 py-1 rounded-md text-[11px] font-medium flex items-center gap-1.5 cursor-pointer transition-all"
          :class="
            store.pickMode === 'start'
              ? 'bg-red-500/20 text-red-300 border border-red-400/40'
              : 'text-slate-400 hover:text-slate-100 border border-transparent'
          "
          @click="setPickMode('start')"
        >
          <Crosshair class="w-3 h-3" />
          选起点
        </button>
        <button
          type="button"
          class="px-2.5 py-1 rounded-md text-[11px] font-medium flex items-center gap-1.5 cursor-pointer transition-all"
          :class="
            store.pickMode === 'end'
              ? 'bg-amber-400/20 text-amber-300 border border-amber-400/40'
              : 'text-slate-400 hover:text-slate-100 border border-transparent'
          "
          @click="setPickMode('end')"
        >
          <Flag class="w-3 h-3" />
          选终点
        </button>
        <span class="w-px h-4 bg-white/10 mx-0.5" />
        <button
          type="button"
          class="px-2.5 py-1 rounded-md text-[11px] font-medium text-slate-400 hover:text-cyan-glow hover:bg-cyan-glow/10 flex items-center gap-1.5 cursor-pointer transition-all border border-transparent disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:text-slate-400 disabled:hover:bg-transparent"
          :disabled="!store.startPoint || !store.hasNavmesh"
          title="导出带 reachableNeighbors 字段的 manifest JSON"
          @click="exportManifest"
        >
          <Download class="w-3 h-3" />
          导出
        </button>
        <button
          type="button"
          class="px-2.5 py-1 rounded-md text-[11px] font-medium text-slate-400 hover:text-red-300 hover:bg-red-500/10 flex items-center gap-1.5 cursor-pointer transition-all border border-transparent"
          @click="clearAll"
        >
          <Trash2 class="w-3 h-3" />
          清除
        </button>
      </div>

      <!-- 空状态 -->
      <div
        v-if="showEmpty"
        class="absolute inset-0 flex flex-col items-center justify-center pointer-events-none animate-fade-in"
      >
        <div
          class="w-20 h-20 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center mb-5 shadow-glass"
        >
          <Hexagon class="w-10 h-10 text-cyan-glow" :stroke-width="1.4" />
        </div>
        <div class="text-base font-medium text-slate-200 mb-1.5">先上传 navmesh GLB</div>
        <div class="text-xs text-slate-400">
          左侧上传 .glb / .gltf · 然后点击「应用并烘焙」生成 navmesh
        </div>
      </div>

      <!-- 烘焙未完成 / 已烘焙未选起点提示 -->
      <div
        v-else-if="hasGeometry && !store.hasNavmesh && !store.loading"
        class="absolute bottom-3 left-3 px-3 py-2 rounded-md glass-card text-[11px] text-slate-300 pointer-events-none animate-fade-in"
      >
        几何已就绪 · 请在左侧调参后点击「应用并烘焙」
      </div>
      <div
        v-else-if="store.hasNavmesh && !store.startPoint && !store.loading"
        class="absolute bottom-3 left-3 px-3 py-2 rounded-md glass-card text-[11px] text-cyan-glow pointer-events-none animate-fade-in"
      >
        在 3D 视口点击地面选起点 · 自动 flood fill 高亮可达 module
      </div>

      <!-- 当前起点坐标 -->
      <div
        v-if="store.startPoint"
        class="absolute bottom-3 left-3 px-3 py-1.5 rounded-md bg-emerald-400/15 border border-emerald-400/30 text-[11px] text-emerald-200 font-mono backdrop-blur-glass"
      >
        起点：({{ store.startPoint.x.toFixed(1) }}, {{ store.startPoint.y.toFixed(1) }}, {{ store.startPoint.z.toFixed(1) }})
      </div>

      <!-- Loading mask -->
      <div
        v-if="store.loading"
        class="absolute inset-0 flex items-center justify-center bg-black/50 backdrop-blur-glass pointer-events-auto"
      >
        <div class="flex flex-col items-center gap-3 px-6 py-5 rounded-xl glass-card">
          <Loader2 class="w-7 h-7 text-cyan-glow animate-spin" />
          <div class="text-[12px] text-slate-200">{{ store.loadingText || '处理中…' }}</div>
        </div>
      </div>

      <!-- 图例 / 统计 -->
      <NavmeshLegend v-if="store.hasNavmesh" />
    </section>

    <div v-if="dragging" class="fixed inset-0 z-50 cursor-col-resize" />
  </main>
</template>
