import { onBeforeUnmount, onMounted, reactive, watch } from 'vue'
import {
  Color,
  OrthographicCamera,
  Vector3,
  WebGLRenderer
} from 'three'
import { useThreeScene } from './useThreeScene'
import { useTerrainStore } from '../stores/terrain'
import { useModulesStore } from '../stores/modules'
import type { MinimapViewState } from '../types/modules'

interface UseMinimapOptions {
  canvasRef: () => HTMLCanvasElement | null
  containerRef: () => HTMLElement | null
  /**
   * 可选：自定义点击回调。
   * - 提供时：默认的"写入 modulesStore.pendingStart"行为被覆盖，由调用方决定怎么用 (worldX, worldZ)
   * - 不提供：保持原行为（写入 modulesStore.pendingStart）
   * - 仍然要求 startPickMode === true 才会触发（与默认一致；不依赖 modulesStore.startPickMode）
   */
  onPick?: (worldX: number, worldZ: number) => void
  /** 与 onPick 配套的 startPickMode 来源（默认读 modulesStore.startPickMode） */
  isPickModeOn?: () => boolean
}

const PADDING_RATIO = 0.06 // 视锥四周留白比例
const CLICK_DRAG_THRESHOLD = 4 // 像素，<= 视为 click

export function useMinimap({ canvasRef, containerRef, onPick, isPickModeOn }: UseMinimapOptions) {
  const { scene } = useThreeScene()
  const store = useTerrainStore()
  const modulesStore = useModulesStore()

  let renderer: WebGLRenderer | null = null
  let camera: OrthographicCamera | null = null
  let rafId = 0
  let resizeObserver: ResizeObserver | null = null

  /** 用户当前视图状态：相对自动取景的偏移与缩放 */
  let userZoom = 1
  let userOffsetX = 0
  let userOffsetZ = 0
  /** 自动取景计算的"基础视锥半宽/半高"（世界单位） */
  let baseHalfW = 50
  let baseHalfH = 50
  /** 自动取景中心 */
  const baseCenter = new Vector3()
  /** 当前应用到 camera 的视锥半宽/半高（含 zoom，含 aspect 适配） */
  let curHalfW = 50
  let curHalfH = 50

  // 拖拽平移状态
  let isDragging = false
  let dragStartX = 0
  let dragStartY = 0
  let dragStartOffsetX = 0
  let dragStartOffsetZ = 0
  let dragMoved = false

  /** 暴露给 overlay 的响应式视图状态 */
  const viewState: MinimapViewState = reactive({
    baseCenterX: 0,
    baseCenterZ: 0,
    userOffsetX: 0,
    userOffsetZ: 0,
    userZoom: 1,
    halfW: 50,
    halfH: 50,
    canvasRect: null
  })

  function syncViewState() {
    viewState.baseCenterX = baseCenter.x
    viewState.baseCenterZ = baseCenter.z
    viewState.userOffsetX = userOffsetX
    viewState.userOffsetZ = userOffsetZ
    viewState.userZoom = userZoom
    viewState.halfW = curHalfW
    viewState.halfH = curHalfH
    const canvas = canvasRef()
    if (canvas) {
      const r = canvas.getBoundingClientRect()
      viewState.canvasRect = { left: r.left, top: r.top, width: r.width, height: r.height }
    }
  }

  function init() {
    const canvas = canvasRef()
    const container = containerRef()
    if (!canvas || !container) return

    renderer = new WebGLRenderer({
      canvas,
      antialias: true,
      alpha: true,
      preserveDrawingBuffer: true // 用于 toDataURL 导出
    })
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
    renderer.setClearColor(new Color(0x0a0f1c), 0)

    camera = new OrthographicCamera(-50, 50, 50, -50, 0.1, 10000)
    // 关键：俯视方向 + up 方向决定地图朝向（让 +X 朝右、+Z 朝下）
    camera.up.set(0, 0, -1)
    camera.position.set(0, 500, 0)
    camera.lookAt(0, 0, 0)

    handleResize()
    if (typeof ResizeObserver !== 'undefined') {
      resizeObserver = new ResizeObserver(handleResize)
      resizeObserver.observe(container)
    }
    window.addEventListener('resize', handleResize)
    window.addEventListener('scroll', syncViewState, { passive: true })

    canvas.addEventListener('wheel', onWheel, { passive: false })
    canvas.addEventListener('pointerdown', onPointerDown)
    window.addEventListener('pointermove', onPointerMove)
    window.addEventListener('pointerup', onPointerUp)
    canvas.addEventListener('dblclick', resetView)

    autoFit()
    animate()
  }

  function getCanvasSize(): { w: number; h: number } {
    const container = containerRef()
    if (!container) return { w: 1, h: 1 }
    return {
      w: container.clientWidth,
      h: container.clientHeight
    }
  }

  function handleResize() {
    const { w, h } = getCanvasSize()
    if (!renderer) return
    const res = store.minimapResolution
    const drawW = res
    const drawH = res
    renderer.setSize(drawW, drawH, false)
    const canvas = canvasRef()
    if (canvas) {
      const display = Math.min(w, h)
      canvas.style.width = `${display}px`
      canvas.style.height = `${display}px`
    }
    updateCameraFrustum()
    store.markMinimapDirty()
    syncViewState()
  }

  function autoFit() {
    // 优先使用 collision merged box（如果有），其次用 terrain
    const cBox = modulesStore.mergedCollisionBox
    const tBox = store.mergedBox
    const box = cBox && !cBox.isEmpty() ? cBox : tBox
    if (!box || box.isEmpty()) {
      baseHalfW = 50
      baseHalfH = 50
      baseCenter.set(0, 0, 0)
    } else {
      const center = new Vector3()
      const size = new Vector3()
      box.getCenter(center)
      box.getSize(size)
      baseCenter.copy(center)
      const halfW = (size.x / 2) * (1 + PADDING_RATIO)
      const halfH = (size.z / 2) * (1 + PADDING_RATIO)
      baseHalfW = Math.max(halfW, 1)
      baseHalfH = Math.max(halfH, 1)
    }
    userZoom = 1
    userOffsetX = 0
    userOffsetZ = 0
    updateCameraFrustum()
    store.markMinimapDirty()
    syncViewState()
  }

  function updateCameraFrustum() {
    if (!camera) return
    const aspect = 1
    let halfW = baseHalfW
    let halfH = baseHalfH
    const boxAspect = halfW / halfH
    if (boxAspect > aspect) {
      halfH = halfW / aspect
    } else {
      halfW = halfH * aspect
    }
    halfW = halfW / userZoom
    halfH = halfH / userZoom
    curHalfW = halfW
    curHalfH = halfH

    camera.left = -halfW
    camera.right = halfW
    camera.top = halfH
    camera.bottom = -halfH

    const topY = ((modulesStore.mergedCollisionBox?.max.y ?? store.mergedBox?.max.y) ?? 100) + 200
    camera.position.set(
      baseCenter.x + userOffsetX,
      topY,
      baseCenter.z + userOffsetZ
    )
    camera.lookAt(baseCenter.x + userOffsetX, 0, baseCenter.z + userOffsetZ)
    camera.near = 0.1
    camera.far = topY + 2000
    camera.updateProjectionMatrix()
    syncViewState()
  }

  function animate() {
    rafId = requestAnimationFrame(animate)
    if (!renderer || !camera) return
    if (!store.minimapDirty) return
    renderer.render(scene, camera)
    store.clearMinimapDirty()
  }

  // ============ 交互 ============
  function onWheel(e: WheelEvent) {
    e.preventDefault()
    const factor = e.deltaY < 0 ? 1.12 : 1 / 1.12
    userZoom = clamp(userZoom * factor, 0.2, 16)
    updateCameraFrustum()
    store.markMinimapDirty()
  }

  function onPointerDown(e: PointerEvent) {
    if (e.button !== 0) return
    const canvas = canvasRef()
    if (!canvas) return
    isDragging = true
    dragMoved = false
    canvas.setPointerCapture?.(e.pointerId)
    dragStartX = e.clientX
    dragStartY = e.clientY
    dragStartOffsetX = userOffsetX
    dragStartOffsetZ = userOffsetZ
  }

  function onPointerMove(e: PointerEvent) {
    if (!isDragging) return
    const canvas = canvasRef()
    if (!canvas) return
    const rect = canvas.getBoundingClientRect()
    if (rect.width === 0 || rect.height === 0) return
    const dxPx = e.clientX - dragStartX
    const dyPx = e.clientY - dragStartY
    if (Math.hypot(dxPx, dyPx) > CLICK_DRAG_THRESHOLD) {
      dragMoved = true
    }
    if (!dragMoved) return
    const halfW = baseHalfW / userZoom
    const halfH = baseHalfH / userZoom
    const worldDx = (dxPx / rect.width) * (halfW * 2)
    const worldDz = (dyPx / rect.height) * (halfH * 2)
    userOffsetX = dragStartOffsetX - worldDx
    userOffsetZ = dragStartOffsetZ - worldDz
    updateCameraFrustum()
    store.markMinimapDirty()
  }

  function onPointerUp(e: PointerEvent) {
    if (!isDragging) return
    isDragging = false
    canvasRef()?.releasePointerCapture?.(e.pointerId)
    if (!dragMoved) {
      // click 行为
      handleClick(e.clientX, e.clientY)
    }
  }

  function handleClick(clientX: number, clientY: number) {
    const pickOn = isPickModeOn ? isPickModeOn() : modulesStore.startPickMode
    if (!pickOn) return
    if (!modulesStore.hasManifest) return
    const w = screenToWorld(clientX, clientY)
    if (!w) return
    if (onPick) {
      onPick(w.x, w.z)
      return
    }
    // 只暂存起点位置；真正的栅格化 + 可达性计算由「生成可达地块树」按钮触发。
    // 这样用户可以反复调整 GLB 旋转、再确认起点，避免每次点击都触发昂贵的 raycast。
    modulesStore.setPendingStart({ x: w.x, z: w.z })
  }

  function resetView() {
    autoFit()
  }

  /** 屏幕坐标 → 世界 (x, z) */
  function screenToWorld(clientX: number, clientY: number): { x: number; z: number } | null {
    const canvas = canvasRef()
    if (!canvas) return null
    const r = canvas.getBoundingClientRect()
    if (r.width === 0 || r.height === 0) return null
    // 0~1 归一化（左上原点）
    const u = (clientX - r.left) / r.width
    const v = (clientY - r.top) / r.height
    // 中心 (0.5, 0.5) → 世界 (camera.position.x, camera.position.z)
    // up=(0,0,-1)：屏幕 +X = 世界 +X，屏幕 +Y = 世界 +Z
    const cx = baseCenter.x + userOffsetX
    const cz = baseCenter.z + userOffsetZ
    const wx = cx + (u - 0.5) * curHalfW * 2
    const wz = cz + (v - 0.5) * curHalfH * 2
    return { x: wx, z: wz }
  }

  /** 世界 (x, z) → 屏幕（相对 canvas 左上角的像素），无 canvas 时返回 null */
  function worldToScreen(wx: number, wz: number): { x: number; y: number } | null {
    const canvas = canvasRef()
    if (!canvas) return null
    const r = canvas.getBoundingClientRect()
    if (r.width === 0 || r.height === 0) return null
    const cx = baseCenter.x + userOffsetX
    const cz = baseCenter.z + userOffsetZ
    const u = (wx - cx) / (curHalfW * 2) + 0.5
    const v = (wz - cz) / (curHalfH * 2) + 0.5
    return { x: u * r.width, y: v * r.height }
  }

  /** 导出当前小地图为 PNG，filename 可选 */
  function exportPNG(filename = `minimap-${Date.now()}.png`) {
    if (!renderer || !camera) return
    renderer.render(scene, camera)
    const canvas = canvasRef()
    if (!canvas) return
    const dataUrl = canvas.toDataURL('image/png')
    const a = document.createElement('a')
    a.href = dataUrl
    a.download = filename
    a.click()
  }

  // 监听数据变化
  const stopWatchTerrains = watch(
    () => store.terrains.length,
    () => autoFit()
  )
  // 监听 terrain 几何变化（如旋转后 box 重算）：用 mergedBox 的 min/max 数值串作为指纹
  const stopWatchTerrainBox = watch(
    () => {
      const b = store.mergedBox
      if (!b || b.isEmpty()) return ''
      return `${b.min.x},${b.min.y},${b.min.z}|${b.max.x},${b.max.y},${b.max.z}`
    },
    () => autoFit()
  )
  const stopWatchModules = watch(
    () => modulesStore.loadedModuleCount,
    () => autoFit()
  )
  const stopWatchRes = watch(
    () => store.minimapResolution,
    () => handleResize()
  )

  onMounted(init)
  onBeforeUnmount(() => {
    stopWatchTerrains()
    stopWatchTerrainBox()
    stopWatchModules()
    stopWatchRes()
    cancelAnimationFrame(rafId)
    window.removeEventListener('resize', handleResize)
    window.removeEventListener('scroll', syncViewState)
    window.removeEventListener('pointermove', onPointerMove)
    window.removeEventListener('pointerup', onPointerUp)
    resizeObserver?.disconnect()
    const canvas = canvasRef()
    if (canvas) {
      canvas.removeEventListener('wheel', onWheel)
      canvas.removeEventListener('pointerdown', onPointerDown)
      canvas.removeEventListener('dblclick', resetView)
    }
    renderer?.dispose()
  })

  return {
    resetView,
    exportPNG,
    viewState,
    screenToWorld,
    worldToScreen,
    syncViewState
  }
}

function clamp(v: number, min: number, max: number) {
  return Math.max(min, Math.min(max, v))
}
