/**
 * useNavmeshRender — 把 PolyRecord[] 渲染成 Three.js 多边形覆盖层。
 *
 * 渲染策略：
 * - 一个 Group 容纳全部 navmesh 可视化：
 *   * `meshFill`     —— 全部 polygon 半透明青色填充（顶点色：可达=翠绿，不可达=青色）
 *   * `wireframe`    —— 全部 polygon 边线（白色 60% 透明）
 *   * `moduleHalos`  —— 各 module worldBox 的颜色覆盖层（绿=可达 / 红=不可达 / 灰=未涉及）
 *   * `markers`      —— 起点 / 终点小球
 *   * `pathLine`     —— funnel 平滑路径折线
 *
 * 关键设计：
 * - 每个 polygon 都做"扇形三角化"（顶点 0 + i + i+1），solo navmesh 的 poly 已经是凸的，
 *   扇形剖分等价于 Recast 内部的方式（detailMesh 提供更精细三角，但对实验工具足够）。
 * - 可达性着色用顶点颜色，避免每次 flood fill 都重建 geometry。flood fill 改变时只更新
 *   `BufferAttribute.color`，性能 < 5ms / 1w polygon。
 * - dispose 严格按 mesh → geometry → material 顺序释放，避免 Three.js 显存泄漏。
 */
import {
  BufferGeometry,
  Color,
  DoubleSide,
  Float32BufferAttribute,
  Group,
  Line,
  LineBasicMaterial,
  LineSegments,
  Material,
  Mesh,
  MeshBasicMaterial,
  Object3D,
  SphereGeometry,
  Vector3,
  type Box3,
  Box3Helper
} from 'three'
import type { PolyRecord } from '../stores/navmesh'

/** 颜色常量 */
const COLOR_REACHABLE = new Color(0x34d399) // emerald
const COLOR_UNREACHABLE_POLY = new Color(0x22d3ee) // cyan
const COLOR_WIREFRAME = new Color(0xffffff)
const COLOR_MODULE_REACH = new Color(0x34d399)
const COLOR_MODULE_UNREACH = new Color(0xef4444)
const COLOR_MODULE_NEUTRAL = new Color(0x64748b)
const COLOR_START_MARKER = new Color(0xef4444)
const COLOR_END_MARKER = new Color(0xfbbf24)
const COLOR_PATH = new Color(0xfacc15)
const COLOR_SELECTED = new Color(0x22d3ee) // cyan-glow，用于 minimap 选中 module 联动高亮

export interface NavmeshRenderHandle {
  /** 挂载到主 scene 的根 group */
  root: Group
  /** 重建 navmesh 几何（烘焙完成后调用） */
  setPolygons(polys: PolyRecord[]): void
  /** flood fill 结果更新（仅更新顶点色，不重建 geometry） */
  setReachable(reachable: Set<number>): void
  /** 设置/清除起点 marker */
  setStartMarker(point: { x: number; y: number; z: number } | null): void
  /** 设置/清除终点 marker */
  setEndMarker(point: { x: number; y: number; z: number } | null): void
  /** 更新 module worldBox 高亮层 */
  setModuleHalos(
    items: Array<{
      name: string
      box: Box3
      state: 'reach' | 'unreach' | 'neutral'
    }>
  ): void
  /** 更新路径折线（flat xyz array） */
  setPath(points: Float32Array): void
  /** 设置/清除"被选中 module"的高亮框（minimap → 3D 联动） */
  setSelectedModule(box: Box3 | null): void
  /** 全量清空（不释放 root） */
  clear(): void
  /** 彻底释放：从父节点摘除 + dispose 所有资源 */
  dispose(): void
}

/**
 * 把每个 polygon 按"扇形三角化"展开为 (v0, vi, vi+1) 三角形，输出 flat positions 与颜色。
 * 同时构建线框（每条 polygon 边一条 LineSegment）。
 */
function buildFillGeometry(polys: PolyRecord[]): {
  fillGeo: BufferGeometry
  wireGeo: BufferGeometry
  /** polyIndex → fill 三角形顶点起始索引（用于 setReachable 快速染色） */
  fillVertexRange: Array<{ start: number; count: number }>
} {
  let triVertCount = 0
  let lineVertCount = 0
  for (const p of polys) {
    const n = p.vertices.length / 3
    triVertCount += (n - 2) * 3
    lineVertCount += n * 2
  }

  const fillPos = new Float32Array(triVertCount * 3)
  const fillCol = new Float32Array(triVertCount * 3)
  const linePos = new Float32Array(lineVertCount * 3)
  const fillVertexRange: Array<{ start: number; count: number }> = new Array(polys.length)

  let fpW = 0
  let fcW = 0
  let lpW = 0
  let vertexCursor = 0

  for (let pi = 0; pi < polys.length; pi++) {
    const verts = polys[pi].vertices
    const n = verts.length / 3
    const triCount = n - 2
    const triVerts = triCount * 3
    fillVertexRange[pi] = { start: vertexCursor, count: triVerts }
    vertexCursor += triVerts

    // 扇形三角化
    const x0 = verts[0]
    const y0 = verts[1]
    const z0 = verts[2]
    for (let i = 1; i < n - 1; i++) {
      // v0
      fillPos[fpW++] = x0
      fillPos[fpW++] = y0 + 0.05 // 微抬高，避免和地表 z-fighting
      fillPos[fpW++] = z0
      // vi
      fillPos[fpW++] = verts[i * 3]
      fillPos[fpW++] = verts[i * 3 + 1] + 0.05
      fillPos[fpW++] = verts[i * 3 + 2]
      // vi+1
      fillPos[fpW++] = verts[(i + 1) * 3]
      fillPos[fpW++] = verts[(i + 1) * 3 + 1] + 0.05
      fillPos[fpW++] = verts[(i + 1) * 3 + 2]
      // 默认色：不可达
      for (let k = 0; k < 3; k++) {
        fillCol[fcW++] = COLOR_UNREACHABLE_POLY.r
        fillCol[fcW++] = COLOR_UNREACHABLE_POLY.g
        fillCol[fcW++] = COLOR_UNREACHABLE_POLY.b
      }
    }

    // 闭合线框
    for (let i = 0; i < n; i++) {
      const a = i
      const b = (i + 1) % n
      linePos[lpW++] = verts[a * 3]
      linePos[lpW++] = verts[a * 3 + 1] + 0.06
      linePos[lpW++] = verts[a * 3 + 2]
      linePos[lpW++] = verts[b * 3]
      linePos[lpW++] = verts[b * 3 + 1] + 0.06
      linePos[lpW++] = verts[b * 3 + 2]
    }
  }

  const fillGeo = new BufferGeometry()
  fillGeo.setAttribute('position', new Float32BufferAttribute(fillPos, 3))
  fillGeo.setAttribute('color', new Float32BufferAttribute(fillCol, 3))

  const wireGeo = new BufferGeometry()
  wireGeo.setAttribute('position', new Float32BufferAttribute(linePos, 3))

  return { fillGeo, wireGeo, fillVertexRange }
}

function disposeObject3D(obj: Object3D) {
  obj.traverse((child) => {
    const m = child as Mesh
    if ((m as Mesh).geometry) (m as Mesh).geometry.dispose()
    const mat = (m as Mesh).material
    if (Array.isArray(mat)) mat.forEach((mm) => (mm as Material).dispose())
    else if (mat) (mat as Material).dispose()
  })
}

export function createNavmeshRender(): NavmeshRenderHandle {
  const root = new Group()
  root.name = 'NavmeshRenderRoot'

  // 子分组（便于按需重建）
  const fillGroup = new Group()
  fillGroup.name = 'navmesh-fill'
  const wireGroup = new Group()
  wireGroup.name = 'navmesh-wire'
  const moduleHaloGroup = new Group()
  moduleHaloGroup.name = 'module-halos'
  const selectedHaloGroup = new Group()
  selectedHaloGroup.name = 'selected-halo'
  const markersGroup = new Group()
  markersGroup.name = 'markers'
  const pathGroup = new Group()
  pathGroup.name = 'path'
  root.add(fillGroup, wireGroup, moduleHaloGroup, selectedHaloGroup, markersGroup, pathGroup)

  // 缓存当前几何对应的 fillVertexRange，用于 setReachable
  let currentPolys: PolyRecord[] = []
  let currentRanges: Array<{ start: number; count: number }> = []
  let currentFillMesh: Mesh | null = null
  let currentWireMesh: LineSegments | null = null
  // polyRef → polyIndex 映射
  let polyRefIndex = new Map<number, number>()

  function clearGroup(g: Group) {
    while (g.children.length > 0) {
      const c = g.children[0]
      g.remove(c)
      disposeObject3D(c)
    }
  }

  function setPolygons(polys: PolyRecord[]) {
    clearGroup(fillGroup)
    clearGroup(wireGroup)
    currentPolys = polys
    polyRefIndex = new Map(polys.map((p, idx) => [p.ref, idx]))

    if (polys.length === 0) {
      currentRanges = []
      currentFillMesh = null
      currentWireMesh = null
      return
    }

    const { fillGeo, wireGeo, fillVertexRange } = buildFillGeometry(polys)
    currentRanges = fillVertexRange

    const fillMat = new MeshBasicMaterial({
      vertexColors: true,
      transparent: true,
      opacity: 0.28,
      side: DoubleSide,
      depthWrite: false
    })
    const fillMesh = new Mesh(fillGeo, fillMat)
    fillMesh.renderOrder = 1
    fillGroup.add(fillMesh)
    currentFillMesh = fillMesh

    const wireMat = new LineBasicMaterial({
      color: COLOR_WIREFRAME,
      transparent: true,
      opacity: 0.55,
      depthWrite: false
    })
    const wireMesh = new LineSegments(wireGeo, wireMat)
    wireMesh.renderOrder = 2
    wireGroup.add(wireMesh)
    currentWireMesh = wireMesh
  }

  function setReachable(reachable: Set<number>) {
    if (!currentFillMesh || currentPolys.length === 0) return
    const colAttr = currentFillMesh.geometry.getAttribute('color') as Float32BufferAttribute
    const arr = colAttr.array as Float32Array
    for (let pi = 0; pi < currentPolys.length; pi++) {
      const range = currentRanges[pi]
      const reach = reachable.has(currentPolys[pi].ref)
      const c = reach ? COLOR_REACHABLE : COLOR_UNREACHABLE_POLY
      const opacityBoost = reach ? 1 : 1
      const base = range.start * 3
      for (let v = 0; v < range.count; v++) {
        arr[base + v * 3] = c.r * opacityBoost
        arr[base + v * 3 + 1] = c.g * opacityBoost
        arr[base + v * 3 + 2] = c.b * opacityBoost
      }
    }
    colAttr.needsUpdate = true
    // 给可达态加点不透明度
    const mat = currentFillMesh.material as MeshBasicMaterial
    mat.opacity = reachable.size > 0 ? 0.4 : 0.28
    mat.needsUpdate = true
  }

  function makeMarker(point: { x: number; y: number; z: number }, color: Color, radius: number) {
    const geo = new SphereGeometry(radius, 16, 12)
    const mat = new MeshBasicMaterial({ color, transparent: true, opacity: 0.95 })
    const m = new Mesh(geo, mat)
    m.position.set(point.x, point.y + radius * 1.5, point.z)
    return m
  }

  let startMesh: Mesh | null = null
  let endMesh: Mesh | null = null

  function estimateMarkerRadius(): number {
    if (currentPolys.length === 0) return 0.5
    // 用 polygons 总 bbox 估一个合理半径
    let mn = Infinity
    let mx = -Infinity
    for (const p of currentPolys) {
      mn = Math.min(mn, p.bmin.x, p.bmin.z)
      mx = Math.max(mx, p.bmax.x, p.bmax.z)
    }
    const span = mx - mn
    return Math.min(1.5, Math.max(0.25, span * 0.004))
  }

  function setStartMarker(point: { x: number; y: number; z: number } | null) {
    if (startMesh) {
      markersGroup.remove(startMesh)
      disposeObject3D(startMesh)
      startMesh = null
    }
    if (point) {
      startMesh = makeMarker(point, COLOR_START_MARKER, estimateMarkerRadius())
      markersGroup.add(startMesh)
    }
  }

  function setEndMarker(point: { x: number; y: number; z: number } | null) {
    if (endMesh) {
      markersGroup.remove(endMesh)
      disposeObject3D(endMesh)
      endMesh = null
    }
    if (point) {
      endMesh = makeMarker(point, COLOR_END_MARKER, estimateMarkerRadius())
      markersGroup.add(endMesh)
    }
  }

  function setModuleHalos(
    items: Array<{ name: string; box: Box3; state: 'reach' | 'unreach' | 'neutral' }>
  ) {
    clearGroup(moduleHaloGroup)
    for (const it of items) {
      if (it.box.isEmpty()) continue
      const color =
        it.state === 'reach'
          ? COLOR_MODULE_REACH
          : it.state === 'unreach'
            ? COLOR_MODULE_UNREACH
            : COLOR_MODULE_NEUTRAL
      const helper = new Box3Helper(it.box, color)
      const mat = helper.material as LineBasicMaterial
      mat.transparent = true
      mat.opacity = it.state === 'neutral' ? 0.2 : it.state === 'reach' ? 0.85 : 0.7
      helper.userData.moduleName = it.name
      moduleHaloGroup.add(helper)
    }
  }

  function setPath(points: Float32Array) {
    clearGroup(pathGroup)
    if (points.length < 6) return
    // 微抬高
    const lifted = new Float32Array(points.length)
    for (let i = 0; i < points.length; i += 3) {
      lifted[i] = points[i]
      lifted[i + 1] = points[i + 1] + 0.15
      lifted[i + 2] = points[i + 2]
    }
    const geo = new BufferGeometry()
    geo.setAttribute('position', new Float32BufferAttribute(lifted, 3))
    const mat = new LineBasicMaterial({
      color: COLOR_PATH,
      transparent: true,
      opacity: 0.95,
      linewidth: 3
    })
    const line = new Line(geo, mat)
    line.renderOrder = 3
    pathGroup.add(line)

    // 端点 + 中间点小球点缀
    const r = estimateMarkerRadius() * 0.6
    const dotGeo = new SphereGeometry(r, 10, 8)
    const dotMat = new MeshBasicMaterial({ color: COLOR_PATH, transparent: true, opacity: 0.9 })
    const v = new Vector3()
    for (let i = 0; i < lifted.length; i += 3) {
      v.set(lifted[i], lifted[i + 1], lifted[i + 2])
      const m = new Mesh(dotGeo, dotMat)
      m.position.copy(v)
      pathGroup.add(m)
    }
  }

  function setSelectedModule(box: Box3 | null) {
    clearGroup(selectedHaloGroup)
    if (!box || box.isEmpty()) return
    // 主体粗框：cyan-glow，比 module halo 显眼
    const helper = new Box3Helper(box, COLOR_SELECTED)
    const mat = helper.material as LineBasicMaterial
    mat.transparent = true
    mat.opacity = 0.95
    mat.depthTest = false
    helper.renderOrder = 5
    selectedHaloGroup.add(helper)
  }

  function clear() {
    clearGroup(fillGroup)
    clearGroup(wireGroup)
    clearGroup(moduleHaloGroup)
    clearGroup(selectedHaloGroup)
    clearGroup(markersGroup)
    clearGroup(pathGroup)
    currentPolys = []
    currentRanges = []
    currentFillMesh = null
    currentWireMesh = null
    startMesh = null
    endMesh = null
    polyRefIndex.clear()
  }

  function dispose() {
    clear()
    root.parent?.remove(root)
  }

  // 暴露给外部一个查 polyIndex 的 helper（path render 用不到，但保留 API 完整性）
  void polyRefIndex
  void currentWireMesh

  return {
    root,
    setPolygons,
    setReachable,
    setStartMarker,
    setEndMarker,
    setModuleHalos,
    setPath,
    setSelectedModule,
    clear,
    dispose
  }
}
