<script setup lang="ts">
/**
 * NavmeshMinimap — Navmesh 实验台左侧的二维平面地形图。
 *
 * 设计（对齐 AnchorMinimap + AnchorOverlay 的画法，避免坐标系错位）：
 * - 复用 useMinimap：共享 useThreeScene 全局 scene 渲染地形 GLB 俯视图
 *   （地形、navmesh fill、module halo、起终点 marker 都会一起出现在小地图上）
 * - 上层叠 2D Canvas overlay：使用 viewState (baseCenter + offset + halfW/halfH) +
 *   container.clientWidth/Height 计算 worldToScreen，与 AnchorOverlay 完全一致
 *   （SVG 方案因为 canvas 居中显示导致坐标系不对齐，已废弃）
 * - 点击：在 overlay 上转换为世界坐标，命中 module.worldBox.containsPoint(xz) → 选中
 *
 * 选中后写 navmeshStore.selectedModuleId；上层 NavmeshView 监听并调用
 * useNavmeshPreview.focusBox + render.setSelectedModule 完成 3D 联动。
 *
 * @changelog
 * | 版本   | 变更说明                                                                         | 关联                                          |
 * | v1.0.0 | 初始实现：二维 module 选择小地图（SVG 版）                                        | REQ: navmesh-minimap-module-select TECH: ad-hoc |
 * | v1.1.0 | SVG → 2D canvas overlay：对齐 AnchorOverlay 画法，修复矩形被拉伸/偏移的问题       | REQ: navmesh-minimap-module-select TECH: ad-hoc |
 * /@changelog
 *
 * @author fancylin
 */
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Map as MapIcon, Maximize2 } from 'lucide-vue-next'
import { useMinimap } from '../composables/useMinimap'
import { useTerrainStore } from '../stores/terrain'
import { useModulesStore } from '../stores/modules'
import { useNavmeshStore } from '../stores/navmesh'

const containerRef = ref<HTMLDivElement | null>(null)
const canvasRef = ref<HTMLCanvasElement | null>(null)
const overlayRef = ref<HTMLCanvasElement | null>(null)

const terrainStore = useTerrainStore()
const modulesStore = useModulesStore()
const navmeshStore = useNavmeshStore()

/* ============================================================
 * 拾取：禁用 useMinimap 默认的 pickMode（写 pendingStart）
 * 我们仅用它做 pan/zoom + 渲染 + 屏幕↔世界换算；
 * module 选择走自己的 overlay click 事件
 * ============================================================ */
const { resetView, viewState } = useMinimap({
  canvasRef: () => canvasRef.value,
  containerRef: () => containerRef.value,
  isPickModeOn: () => false
})

const isCanvasEmpty = computed(
  () => terrainStore.isEmpty && modulesStore.loadedModuleCount === 0
)

const selectedModuleId = computed(() => navmeshStore.selectedModuleId)

/** 给 module 名生成稳定 hue（与 AnchorOverlay 同款） */
function moduleHueFor(name: string): number {
  let h = 0
  for (let i = 0; i < name.length; i++) {
    h = (h * 31 + name.charCodeAt(i)) | 0
  }
  return Math.abs(h) % 360
}

/* ============================================================
 * Overlay 绘制：完全复刻 AnchorOverlay 的几何换算
 *   worldToScreen(wx, wz):
 *     u = (wx - (baseCenter+offset).x) / (halfW * 2) + 0.5
 *     v = (wz - (baseCenter+offset).z) / (halfH * 2) + 0.5
 *     screen = (u * containerW, v * containerH)
 * ============================================================ */
let rafId = 0
let needsRedraw = true
function requestRedraw() {
  needsRedraw = true
}

interface DrawnRect {
  name: string
  x: number
  y: number
  w: number
  h: number
}
/** 最近一次绘制时累积的矩形列表，给 hit-test 用 */
let lastRects: DrawnRect[] = []

function loop() {
  rafId = requestAnimationFrame(loop)
  if (!needsRedraw) return
  draw()
  needsRedraw = false
}

function draw() {
  const canvas = overlayRef.value
  const container = containerRef.value
  if (!canvas || !container) return
  const w = container.clientWidth
  const h = container.clientHeight
  if (w === 0 || h === 0) return

  const dpr = Math.min(window.devicePixelRatio, 2)
  if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
    canvas.width = Math.round(w * dpr)
    canvas.height = Math.round(h * dpr)
    canvas.style.width = `${w}px`
    canvas.style.height = `${h}px`
  }
  const ctx = canvas.getContext('2d')
  if (!ctx) return
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  ctx.clearRect(0, 0, w, h)

  const cx = viewState.baseCenterX + viewState.userOffsetX
  const cz = viewState.baseCenterZ + viewState.userOffsetZ
  const halfW = viewState.halfW
  const halfH = viewState.halfH
  if (halfW <= 0 || halfH <= 0) {
    lastRects = []
    return
  }

  const worldToScreen = (wx: number, wz: number) => {
    const u = (wx - cx) / (halfW * 2) + 0.5
    const v = (wz - cz) / (halfH * 2) + 0.5
    return { x: u * w, y: v * h }
  }

  const reachable = navmeshStore.reachableModuleIds
  const unreachable = navmeshStore.unreachableModuleIds
  const selId = selectedModuleId.value

  const rects: DrawnRect[] = []

  // ---------- 第 1 遍：所有 module 矩形（按 reachable / unreachable / 中性配色） ----------
  for (const m of modulesStore.modules) {
    if (m.worldBox.isEmpty()) continue
    const p1 = worldToScreen(m.worldBox.min.x, m.worldBox.min.z)
    const p2 = worldToScreen(m.worldBox.max.x, m.worldBox.max.z)
    const x = Math.min(p1.x, p2.x)
    const y = Math.min(p1.y, p2.y)
    const rw = Math.abs(p2.x - p1.x)
    const rh = Math.abs(p2.y - p1.y)
    rects.push({ name: m.name, x, y, w: rw, h: rh })

    if (m.name === selId) continue // 选中态最后画

    let fill = 'rgba(148,163,184,0.06)' // slate
    let stroke = 'rgba(148,163,184,0.55)'
    let lw = 1
    if (reachable.has(m.name)) {
      fill = 'rgba(52,211,153,0.10)' // emerald
      stroke = 'rgba(52,211,153,0.75)'
    } else if (unreachable.has(m.name)) {
      fill = 'rgba(244,63,94,0.08)' // rose
      stroke = 'rgba(244,63,94,0.65)'
    }
    ctx.fillStyle = fill
    ctx.strokeStyle = stroke
    ctx.lineWidth = lw
    ctx.fillRect(x, y, rw, rh)
    ctx.strokeRect(x + 0.5, y + 0.5, rw - 1, rh - 1)
  }

  // ---------- 第 2 遍：选中 module 高亮（cyan-glow，覆盖在最上面）----------
  if (selId) {
    const m = modulesStore.modules.find((mm) => mm.name === selId)
    if (m && !m.worldBox.isEmpty()) {
      const p1 = worldToScreen(m.worldBox.min.x, m.worldBox.min.z)
      const p2 = worldToScreen(m.worldBox.max.x, m.worldBox.max.z)
      const x = Math.min(p1.x, p2.x)
      const y = Math.min(p1.y, p2.y)
      const rw = Math.abs(p2.x - p1.x)
      const rh = Math.abs(p2.y - p1.y)
      ctx.save()
      ctx.fillStyle = 'rgba(34,211,238,0.18)'
      ctx.fillRect(x, y, rw, rh)
      ctx.strokeStyle = 'rgba(34,211,238,0.95)'
      ctx.lineWidth = 2
      ctx.setLineDash([6, 4])
      ctx.strokeRect(x + 0.5, y + 0.5, rw - 1, rh - 1)
      ctx.restore()
    }
  }

  // ---------- 第 3 遍：模块名标签（小字 + 阴影描边）----------
  ctx.font = '10px Inter, system-ui, sans-serif'
  ctx.textAlign = 'left'
  ctx.textBaseline = 'top'
  ctx.shadowColor = 'rgba(0,0,0,0.75)'
  ctx.shadowBlur = 2
  for (const r of rects) {
    if (r.w < 16 || r.h < 12) continue // 过小的不画字，避免糊一片
    const isSel = r.name === selId
    ctx.fillStyle = isSel ? 'rgba(165,243,252,0.98)' : 'rgba(226,232,240,0.78)'
    // 留 2px padding
    ctx.fillText(r.name, r.x + 2, r.y + 2)
  }
  ctx.shadowBlur = 0

  lastRects = rects
}

/* ---------- 点击 hit-test：转换为世界坐标 → 包含点的最小 module ---------- */
function onOverlayClick(e: MouseEvent) {
  const container = containerRef.value
  if (!container) return
  const rect = container.getBoundingClientRect()
  const localX = e.clientX - rect.left
  const localY = e.clientY - rect.top
  // 命中：从后往前遍历（后画的在视觉上在上方），优先选中可视面积更小的（更精准）
  const candidates: DrawnRect[] = []
  for (const r of lastRects) {
    if (localX >= r.x && localX <= r.x + r.w && localY >= r.y && localY <= r.y + r.h) {
      candidates.push(r)
    }
  }
  if (candidates.length === 0) {
    // 点空地：清除选中
    if (selectedModuleId.value) navmeshStore.setSelectedModule(null)
    return
  }
  // 选中视觉面积最小的（嵌套 module 时更精确）
  candidates.sort((a, b) => a.w * a.h - b.w * b.h)
  const hit = candidates[0]
  if (selectedModuleId.value === hit.name) {
    navmeshStore.setSelectedModule(null)
  } else {
    navmeshStore.setSelectedModule(hit.name)
  }
}

/* ---------- 重绘触发：viewState / modules / 选中态 / reachable 集合变化 ---------- */
watch(
  () => [
    viewState.userZoom,
    viewState.userOffsetX,
    viewState.userOffsetZ,
    viewState.halfW,
    viewState.halfH,
    viewState.baseCenterX,
    viewState.baseCenterZ,
    modulesStore.modules.length,
    modulesStore.loadedModuleCount,
    navmeshStore.selectedModuleId,
    navmeshStore.reachableModuleIds.size,
    navmeshStore.unreachableModuleIds.size
  ],
  () => requestRedraw(),
  { deep: false }
)

onMounted(() => {
  rafId = requestAnimationFrame(loop)
})
onBeforeUnmount(() => cancelAnimationFrame(rafId))
</script>

<template>
  <div class="glass-card p-3 flex flex-col gap-3 animate-fade-in">
    <!-- 标题栏 -->
    <div class="flex items-center justify-between px-1">
      <div class="flex items-center gap-2">
        <MapIcon class="w-4 h-4 text-cyan-glow" />
        <span class="text-sm font-semibold tracking-wide">二维地形 · Module</span>
        <span
          v-if="modulesStore.loadedModuleCount > 0"
          class="chip text-cyan-300/80 border-cyan-400/30"
        >
          {{ modulesStore.loadedModuleCount }} modules
        </span>
      </div>
      <button
        class="px-2 py-0.5 text-[11px] rounded border border-white/10 text-slate-400 hover:text-cyan-glow hover:border-cyan-glow/40 transition-colors cursor-pointer flex items-center gap-1"
        :disabled="isCanvasEmpty"
        :class="{ 'opacity-40 cursor-not-allowed': isCanvasEmpty }"
        title="重置视图（双击地图也可）"
        @click="resetView"
      >
        <Maximize2 class="w-3 h-3" />
        重置
      </button>
    </div>

    <!-- 小地图画布 + 2D canvas overlay -->
    <!-- 监听容器 click：useMinimap 拖拽 < 4px 视为 click，会冒泡到容器；
         overlay/canvas 都设 pointer-events 透传策略（见下），不打断 useMinimap 的 pan/zoom -->
    <div
      ref="containerRef"
      class="relative aspect-square w-full rounded-lg overflow-hidden bg-black/40 border border-cyan-400/15"
      :style="{ boxShadow: 'inset 0 0 16px rgba(34,211,238,0.10)' }"
      @click="onOverlayClick"
    >
      <!-- 底层 three.js 渲染（地形 + module halo） -->
      <canvas
        ref="canvasRef"
        class="block mx-auto select-none"
        :class="isCanvasEmpty ? 'opacity-0' : 'cursor-grab active:cursor-grabbing'"
      />

      <!-- 上层 overlay：画 module 矩形 + 标签 + 选中高亮 -->
      <!-- pointer-events: none → 不拦截 wheel/pointerdown，让 useMinimap 正常 pan/zoom；
           click 事件由父容器统一处理（useMinimap 的"非拖拽"阈值小于 4px 时 click 才会触发） -->
      <canvas
        ref="overlayRef"
        v-show="!isCanvasEmpty"
        class="absolute inset-0 pointer-events-none"
      />

      <!-- 空态 -->
      <div
        v-if="isCanvasEmpty"
        class="absolute inset-0 flex flex-col items-center justify-center text-slate-500 pointer-events-none"
      >
        <MapIcon class="w-8 h-8 mb-2 opacity-50" :stroke-width="1.4" />
        <div class="text-xs">上传 navmesh GLB / manifest 后自动生成</div>
      </div>

      <!-- 角标 -->
      <div
        v-if="!isCanvasEmpty"
        class="absolute bottom-1.5 right-2 text-[10px] text-cyan-glow/80 font-mono tracking-wider pointer-events-none"
      >
        2D · CLICK TO FOCUS
      </div>
    </div>

    <!-- 当前选中提示 -->
    <div
      v-if="selectedModuleId"
      class="flex items-center justify-between gap-2 px-2 py-1.5 rounded-md text-[11px] bg-cyan-glow/10 border border-cyan-glow/30 text-cyan-200"
    >
      <span class="truncate">
        已选中
        <span class="font-mono text-cyan-glow">{{ selectedModuleId }}</span>
      </span>
      <button
        class="shrink-0 text-cyan-300 hover:text-white cursor-pointer"
        @click="navmeshStore.setSelectedModule(null)"
      >
        清除
      </button>
    </div>

    <!-- 防 unused（hue 函数预留给后续按 module 上色） -->
    <span v-if="false">{{ moduleHueFor('') }}</span>
  </div>
</template>
